#!/usr/bin/env node
/**
 * Pre-build precondition check for `npm run build`.
 *
 * `akvj/src/public/projects/` and `akvj/src/public/active-project.json` are
 * generated by the clip pipeline (`npm run clips`) and are gitignored. Vite
 * copies whatever is in `akvj/src/public/` into `dist/`, so a build run without
 * the pipeline having ever executed produces a `dist/` with no projects, no
 * clips.json, and no active-project.json — and exits 0. The app then boots to a
 * black canvas with no signal that the build was incomplete.
 *
 * This script fails loudly in that case, naming the command that produces the
 * missing tree, so `npm run build` no longer ships a clip-less artifact.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..');
const PUBLIC_ROOT = path.join(REPO_ROOT, 'akvj', 'src', 'public');

/**
 * Required generated artifacts. The clip pipeline writes both; Vite copies both
 * into `dist/`. Either missing means the pipeline has not run.
 */
const REQUIRED_PATHS = [path.join(PUBLIC_ROOT, 'projects', 'index.json'), path.join(PUBLIC_ROOT, 'active-project.json')];

const FIX_MESSAGE = ['', 'The generated clip tree is missing — `npm run build` would produce a clip-less dist/.', 'Run one of:', '  npm run clips        # generate the clip tree only', '  npm run build:full   # generate the clip tree, then build', '  npm run build:all    # clips + akvj + mainframe', ''].join('\n');

/**
 * Return the list of required generated artifacts that are absent.
 * @param {string[]} [paths] - override for testing
 * @returns {string[]}
 */
export function missingArtifacts(paths = REQUIRED_PATHS) {
	return paths.filter(p => !fs.existsSync(p));
}

function main() {
	const missing = missingArtifacts();
	if (missing.length === 0) {
		return;
	}
	console.error(`[verify-clip-tree] Missing generated artifacts:`);
	for (const p of missing) {
		console.error(`  - ${path.relative(REPO_ROOT, p)}`);
	}
	console.error(FIX_MESSAGE);
	process.exit(1);
}

const scriptPath = process.argv[1] ?? '';
const isCli = scriptPath && path.resolve(scriptPath) === fileURLToPath(import.meta.url);

if (isCli) {
	main();
}
